var a=`1368-arepa-reina-pepiada`;var n=`world-1368`;var t=`VE`;var o=`south-america`;var r=4;var s=69;var l={en:`Arepa Reina Pepiada`,ua:`Арепа рейна пеп'яда`};var h={en:`Arepa Reina Pepiada is a dish from Venezuela featuring arepa flour, chicken breast, avocado, mayonnaise. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Арепа рейна пеп'яда, страва кухні країни Венесуела з такими основними складниками: борошно для ареп, куряча грудка, авокадо, майонез. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var d=[{en:`Mix the corn flour with the measured water and salt until a soft cohesive, non-sticky masa forms. Rest covered for about 10 minutes; this gluten-free dough does not become elastic like wheat dough.`,ua:`Змішайте кукурудзяне борошно із зазначеною водою й сіллю до м’якої цілісної маси, що не липне. Накрийте на приблизно 10 хвилин; таке безглютенове тісто не стає еластичним, як пшеничне.`,t:[`mixing`,`kneading`,`resting-dough`],m:13,i:[[`arepa-flour`,450,`g`],[`water`,550,`ml`],[`table-salt`,8,`g`]]},{en:`Shape, press or roll the prepared dough or mixture into portions appropriate to this dish.`,ua:`Розпластайте, розкачайте або сформуйте з підготовленого тіста чи маси порції потрібної форми.`,t:[`pressing`,`rolling-out-dough`],m:9,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 15 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 15 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:15,i:[[`canola-oil`,60,`ml`]]},{en:`Poach chicken breast until fully cooked to 74°C, then cool slightly and shred before mixing the cold avocado filling.`,ua:`Відваріть куряче філе до 74°C, трохи остудіть і розберіть на волокна перед змішуванням із холодною начинкою з авокадо.`,t:[`poaching`],m:17,i:[[`chicken-breast`,500,`g`],[`water`,600,`ml`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:12,i:[[`avocado`,3,`pcs`],[`mayonnaise`,110,`g`],[`lime-juice`,35,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,22,`g`]]}];var u={slug:a,id:n,country:`VE`,region:o,servings:4,minutes:69,title:l,text:h,steps:d};export{t as country,u as default,n as id,s as minutes,o as region,r as servings,a as slug,d as steps,h as text,l as title};